logmsg('Loading original RNA once for sparse aggregation');s<-qread(input,nthreads=2);stopifnot(setequal(colnames(s),ids));lay<-Layers(s[['RNA']]);counts_layers<-grep('^counts($|\\.)',lay,value=TRUE);stopifnot(length(counts_layers)==1);x<-LayerData(s[['RNA']],layer=counts_layers)[,ids,drop=FALSE];stopifnot(inherits(x,'sparseMatrix'),!anyDuplicated(rownames(x)),all(is.finite(x@x)),all(x@x>=0),all(x@x==floor(x@x)));lib<-colSums(x);stopifnot(all(lib>0));wt(data.table(n_features=nrow(x),n_cells=ncol(x),nnz=length(x@x),noninteger=sum(x@x!=floor(x@x)),counts_layer=counts_layers),'00_audit/RNA_counts_check.tsv');wt(data.table(gene_id=rownames(x)),'00_audit/RNA_features.tsv.gz')
y<-LayerData(s[['RNA']],layer='data')[,ids,drop=FALSE];stopifnot(identical(dimnames(x),dimnames(y)));ix<-unique(round(seq(1,length(ids),length.out=25)));test<-x[,ix,drop=FALSE]%*%Diagonal(x=1e4/lib[ix]);test@x<-log1p(test@x);diff<-max(abs(test-y[,ix,drop=FALSE]));if(diff>1e-6){y<-x%*%Diagonal(x=1e4/lib);dimnames(y)<-dimnames(x);y@x<-log1p(y@x)};wt(data.table(data_verified=diff<=1e-6,max_abs_difference=diff,display='ordinary LogNormalize scale.factor10000'),'00_audit/RNA_data_check.tsv');capture.output(Reductions(s),s@commands,file=out('00_audit/RNA_source_commands.txt'));if('umap_allgene'%in%Reductions(s)){em<-Embeddings(s[['umap_allgene']]);stopifnot(setequal(rownames(em),ids));saveq(em[ids,],'00_audit/original_RNA_umap.qs')};rm(s,test);gc();det<-x;det@x[]<-1
samples<-sort(unique(md$sample));smeta<-unique(md[,.(sample,dataset,source)]);smeta<-smeta[match(samples,sample)];sind<-sparseMatrix(i=seq_along(ids),j=match(md$sample,samples),x=1,dims=c(length(ids),length(samples)));smeta[,`:=`(n_cells=as.numeric(colSums(sind)),library_size=as.numeric(crossprod(sind,lib)))];tot<-list(meta=smeta,counts=x%*%sind,expression_sum=y%*%sind,detected_sum=det%*%sind);saveq(tot,'04_pseudobulk_markers/sample_totals.qs');wt(smeta,'04_pseudobulk_markers/sample_totals_metadata.tsv');rm(tot)
